class Solution {
public:
    string betterCompression(string compressed) {
        long long count[26] = {};
        for (int i = 0; i < (int)compressed.size();) {
            int c = compressed[i++] - 'a';
            long long x = 0;
            while (i < (int)compressed.size() && isdigit(compressed[i]))
                x = x * 10 + compressed[i++] - '0';
            count[c] += x;
        }
        string ans;
        for (int i = 0; i < 26; ++i) if (count[i])
            ans += string(1, char('a' + i)) + to_string(count[i]);
        return ans;
    }
};
